function minimumSum(nums) {
  const n = nums.length;
  // rightMin[j] is the smallest value strictly to the right of j.
  const rightMin = new Array(n).fill(Infinity);
  for (let j = n - 2; j >= 0; j--) {
    rightMin[j] = Math.min(rightMin[j + 1], nums[j + 1]);
  }
  let leftMin = nums[0];
  let best = Infinity;
  for (let j = 1; j < n - 1; j++) {
    if (leftMin < nums[j] && rightMin[j] < nums[j]) {
      best = Math.min(best, leftMin + nums[j] + rightMin[j]);
    }
    leftMin = Math.min(leftMin, nums[j]);
  }
  return best === Infinity ? -1 : best;
}

