function minimumSum(nums) {
  let best = -1;
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      for (let k = j + 1; k < nums.length; k++) {
        if (nums[i] < nums[j] && nums[k] < nums[j]) {
          const sum = nums[i] + nums[j] + nums[k];
          if (best === -1 || sum < best) best = sum;
        }
      }
  return best;
}

