function generate(rand, size) {
  const n = size === 'large' ? 50 : 3 + Math.floor(rand() * 8);
  const top = size === 'large' ? 50 : 1 + Math.floor(rand() * 9);
  const shape = rand();
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  // Sometimes sort the values so that no mountain exists.
  if (shape < 0.1) nums.sort((a, b) => a - b);
  else if (shape < 0.2) nums.sort((a, b) => b - a);
  return [nums];
}
